function.arguments:
{"command": "cd /workspace && python3 - <<'EOF'
import re
d=open('/tmp/t20.raw','rb').read()
i=d.find(b']\n'); j=d.find(b'Script done')
body=d[i+2:j]
rows=body.split(b'\r\n')
pat=re.compile(rb'\x1b\[([0-9;]+)m([^\x1b]*)')
arts=[]
for k in range(1,21):
    r=rows[k]
    idx=r.find(b'seq=')
    art=r[:idx]
    cells=[]
    pos=0
    for m in pat.finditer(art):
        pre=art[pos:m.start()]
        for ch in pre.decode(): cells.append((ch,None))
        code=m.group(1).decode(); txt=m.group(2).decode()
        for ch in txt: cells.append((ch,code))
        pos=m.end()
    for ch in art[pos:].decode(): cells.append((ch,None))
    arts.append(cells)
for n,row in enumerate(arts):
    print(n, len(row))
codes={}
for row in arts:
    for ch,c in row:
        codes[(c)] = codes.get(c,0)+1
print("codes count:",codes)
# unique color per char type
m={}
for row in arts:
    for ch,c in row:
        m.setdefault(ch,set()).add(c)
print(m)
EOF"}

