import re
d=open('/tmp/t20.raw','rb').read()
i=d.find(b']\n'); j=d.find(b'Script done')
body=d[i+2:j]
rows=body.split(b'\r\n')
arts=[]
for k in range(1,21):
    r=rows[k]; idx=r.find(b'seq='); art=r[:idx]
    cells=[]; cur=None; pos=0
    while pos<len(art):
        if art[pos:pos+1]==b'\x1b':
            m=re.match(rb'\x1b\[([0-9;]+)m',art[pos:])
            code=m.group(1).decode(); pos+=m.end()
            if code in ('0','0;22'):
                cur=None
            else:
                cur=code
        else:
            cells.append((art[pos:pos+1].decode(),cur)); pos+=1
    arts.append(cells)
print("lengths:",[len(a) for a in arts])
print("codes by char:")
codes={}
for row in arts:
    for ch,c in row: codes.setdefault(ch,set()).add(c)
print(codes)
cl={'90;1':'g','93;1':'Y','97;1':'W','91;1':'R',None:'.'}
print("COLOR GRID:")
for n,row in enumerate(arts):
    print(f"{n:2d} "+''.join(cl[c] if c in cl else (' ' if ch==' ' else '.') for ch,c in row))
EOF"}

