package main

import (
	"fmt"
	"net"
	"syscall"
	"time"
)

func main() {
	// Approach B: ICMP datagram socket via syscall
	fd, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMP)
	if err != nil { fmt.Println("socket err:", err); return }
	defer syscall.Close(fd)
	err = syscall.Bind(fd, &syscall.SockaddrInet4{Port: 0})
	if err != nil { fmt.Println("bind err:", err); return }
	lsa, _ := syscall.Getsockname(fd)
	fmt.Printf("local after bind: %#v\n", lsa)
	// build ICMP echo
	dst := net.ParseIP("127.0.0.1")
	sa := &syscall.SockaddrInet4{}
	copy(sa.Addr[:], dst.To4())
	data := make([]byte, 24)
	for i := range data { data[i] = byte(i) }
	hdr := []byte{8, 0, 0, 0, 0, 1, 0, 1} // type8 code0 cksum0 id=1 seq=1
	ck := csum(append(hdr, data...))
	hdr[2] = byte(ck >> 8); hdr[3] = byte(ck)
	pkt := append(hdr, data...)
	start := time.Now()
	err = syscall.Sendto(fd, pkt, 0, sa)
	fmt.Println("sendto err:", err, "len", len(pkt))
	if err != nil { return }
	buf := make([]byte, 1500)
	syscall.SetsockoptInt(fd, syscall.SOL_SOCKET, syscall.SO_RCVTIMEO, 0)
	// read with timeout via poll
	n, from, err := syscall.Recvfrom(fd, buf, 0)
	fmt.Println("recv err:", err, "n=", n, "from=", from, "elapsed=", time.Since(start))
	if n > 0 {
		fmt.Printf("recv bytes: %x\n", buf[:n])
	}
}

func csum(b []byte) uint16 {
	var s uint32
	for i := 0; i+1 < len(b); i += 2 { s += uint32(b[i])<<8 | uint32(b[i+1]) }
	if len(b)%2 == 1 { s += uint32(b[len(b)-1]) << 8 }
	for s>>16 != 0 { s = (s & 0xffff) + (s >> 16) }
	return ^uint16(s)
}
EOF
