package main

import (
	"fmt"
	"net"
	"os"
	"syscall"
)

func main() {
	fd, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMP)
	if err != nil { fmt.Println("socket err:", err); return }
	defer syscall.Close(fd)
	err = syscall.Bind(fd, &syscall.SockaddrInet4{Port: 0})
	if err != nil { fmt.Println("bind err:", err); return }
	f := os.NewFile(uintptr(fd), "")
	conn, err := net.FilePacketConn(f)
	if err != nil { fmt.Println("filepacketconn err:", err); return }
	c, ok := conn.(*net.UDPConn)
	fmt.Printf("type ok=%v (%T)\n", ok, conn)
	if !ok { fmt.Println("not udp conn"); return }
	fmt.Println("local:", c.LocalAddr())
	dst := net.ParseIP("127.255.255.255")
	n, err := c.WriteTo([]byte{8, 0, 0, 0, 0, 0, 0, 0}, &net.UDPAddr{IP: dst, Port: 0})
	fmt.Printf("write n=%d err=%v\n", n, err)
	buf := make([]byte, 1500)
	n, ra, err := c.ReadFrom(buf)
	fmt.Printf("read n=%d addr=%v err=%v\n", n, ra, err)
}
EOF
