function.arguments:
{"command": "mkdir -p /tmp/t5 && cd /tmp/t5 && cat > main.go <<'EOF'
package main

import (
	"fmt"
	"net"
	"os"
	"syscall"
	"time"
)

func csum(b []byte) uint16 {
	var s uint32
	for i := 0; i+1 < len(b); i += 2 { s += uint32(b[i])<<8 | uint32(b[i+1]) }
	if len(b)%2 == 1 { s += uint32(b[len(b)-1]) << 8 }
	for s>>16 != 0 { s = (s & 0xffff) + (s >> 16) }
	return ^uint16(s)
}

func main() {
	fd, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMP)
	if err != nil { fmt.Println("socket err:", err); return }
	defer syscall.Close(fd)
	if err := syscall.Bind(fd, &syscall.SockaddrInet4{Port: 0}); err != nil { fmt.Println(err); return }
	if err := syscall.SetsockoptInt(fd, syscall.IPPROTO_IP, 12 /*IP_RECVTTL*/, 1); err != nil {
		fmt.Println("set IP_RECVTTL err:", err)
	} else { fmt.Println("IP_RECVTTL ok") }
	f := os.NewFile(uintptr(fd), "")
	conn, _ := net.FilePacketConn(f)
	c := conn.(*net.UDPConn)
	data := make([]byte, 24)
	for i := range data { data[i] = byte(i) }
	dst := net.ParseIP("127.0.0.1")
	hdr := []byte{8, 0, 0, 0, 0, 0, 0, 0}
	pkt := append(hdr, data...)
	ck := csum(pkt)
	pkt[2] = byte(ck >> 8); pkt[3] = byte(ck)
	if _, err := c.WriteTo(pkt, &net.UDPAddr{IP: dst, Port: 0}); err != nil { fmt.Println("send:", err) }
	buf := make([]byte, 2000)
	ctl := make([]byte, 512)
	deadline := time.Now().Add(300 * time.Millisecond)
	for {
		if time.Now().After(deadline) { break }
		n, oobn, flags, ra, err := syscall.Recvmsg(fd, buf, ctl, 0)
		fmt.Printf("recvmsg n=%d oobn=%d flags=%d ra=%v err=%v ctl=%x\n", n, oobn, flags, ra, err, ctl[:oobn])
		if err == nil && n > 0 { break }
	}
}
EOF
