    if not g: print(w,"??"); continue
    descs=[]
    for grp in g:
        # join with ' ' handling the empty line (hyphenation)
        s=''
        for i,x in enumerate(grp):
            if x=='': s+='\n'
            else: s+= ('' if s.endswith('\n') or s=='' else ' ')+x
        descs.append(s)
    # max non-hyphenated line length (absolute)
    mx=0
    for grp in g:
        for x in grp:
            if x: mx=max(mx, IND+len(x))
    print(w, mx, descs)
