 '-V': 'Show version',
 '-h': 'Show this help message',
}
def greedy(s, avail):
    words = s.split(' ')
    lines=[]; cur=''
    for w in words:
        if cur=='': cur=w
        elif len(cur)+1+len(w) <= avail: cur += ' '+w
        else: lines.append(cur); cur=w
    if cur: lines.append(cur)
    return lines
def observe(w):
    out = run(['./executable','--help'], w).decode()
    lines = out.split('\n')
    groups=[]; cur=None
    for l in lines:
        if l.startswith('  -'):
            if cur is not None and cur: groups.append(cur)
            cur=[l[19:]]
        elif l.startswith(' '*19) and cur is not None and len(l)>=19 and l[19:]!='':
            cur.append(l[19:])
        else:
            if cur is not None and cur: groups.append(cur)
            cur=None
    if cur: groups.append(cur)
    return groups
for w in range(20,72):
    obs = observe(w)
    res=[]
    for k,opt in enumerate(['-c','-P','-V','-h']):
        avail = w-19
        sim = greedy(DESCS[opt], avail)
