package main

import (
	"fmt"
	"net"
	"time"
)

func csum(b []byte) uint16 {
	var s uint32
	for i := 0; i+1 < len(b); i += 2 { s += uint32(b[i])<<8 | uint32(b[i+1]) }
	if len(b)%2 == 1 { s += uint32(b[len(b)-1]) << 8 }
	for s>>16 != 0 { s = (s & 0xffff) + (s >> 16) }
	return ^uint16(s)
}

func main() {
	// plain UDP socket approach
	c, err := net.ListenPacket("udp4", "0.0.0.0")
	if err != nil { fmt.Println("listen:", err); return }
	uc := c.(*net.UDPConn)
	fmt.Println("local:", uc.LocalAddr())
	data := make([]byte, 24)
	for i := range data { data[i] = byte(i) }
	hdr := []byte{8, 0, 0, 0, 0, 0, 0, 0}
	pkt := append(hdr, data...)
	ck := csum(pkt)
	pkt[2] = byte(ck >> 8); pkt[3] = byte(ck)
	// write as UDP datagram to the raw IP (no port)
	dst := net.ParseIP("127.0.0.1")
	n, err := uc.WriteTo(pkt, &net.IPAddr{IP: dst})
	fmt.Printf("write as IPAddr: n=%d err=%v\n", n, err)
	buf := make([]byte, 2000)
	uc.SetReadDeadline(time.Now().Add(300 * time.Millisecond))
	n, ra, err := uc.ReadFrom(buf)
	fmt.Printf("read: n=%d addr=%v(%T) err=%v bytes=%x\n", n, ra, ra, err, buf[:n])
}
EOF
