{"command": "cd /workspace && cat > args.go <<'GOEOF'
package main

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// errHelp is returned by the argument parser as soon as the help flag is
// seen.  The caller is expected to print the help text and exit with
// status zero.
var errHelp = errors.New("help requested")

// option describes one command line flag.
type option struct {
	short byte
	long  string
	arg   bool   // the flag takes a value
	help  string // description shown by --help
}

func (o option) name() string {
	if o.arg {
		return fmt.Sprintf("-%c, --%s=", o.short, o.long)
	}
	return fmt.Sprintf("-%c, --%s", o.short, o.long)
}

func (o option) plainName() string {
	return fmt.Sprintf("-%c, --%s", o.short, o.long)
}

var knownOptions = []option{
	{'c', "count", true, "Stop after <count> replies (default: 20)"},
	{'P', "privilege", false, "Enable privileged mode"},
	{'V', "version", false, "Show version"},
	{'h', "help", false, "Show this help message"},
}

func lookupLong(name string) *option {
	for i := range knownOptions {
		if knownOptions[i].long == name {
			return &knownOptions[i]
		}
	}
	return nil
}

func lookupShort(c byte) *option {
	for i := range knownOptions {
		if knownOptions[i].short == c {
			return &knownOptions[i]
		}
	}
	return nil
}

// settings holds the values collected from the command line.
type settings struct {
	count     int64
	privilege bool
	version   bool
}

func newSettings() *settings {
	return &settings{count: 20}
}

// looksLikeOption reports whether the argument should be interpreted as an
// option rather than as a value.  A lone dash and negative numbers are
// treated as plain values.
func looksLikeOption(arg string) bool {
	if arg == "-" {
		return false
	}
	if len(arg) < 2 || arg[0] != '-' {
		return false
	}
	if arg[1] == '-' {
		// a long option, but not the "--" terminator nor things like "---"
		return len(arg) > 2 && arg[2] != '-'
	}
	if arg[1] >= '0' && arg[1] <= '9' {
		return false
	}
	return true
}

// parseArgv interprets the command line the same way the flag parser used
// by the original program does.  On success it returns the settings and the
// remaining positional arguments.
func parseArgv(argv []string) (*settings, []string, error) {
	st := newSettings()
	positional := []string{}
	terminator := false

	for i := 0; i < len(argv); i++ {
		arg := argv[i]

		if terminator {
			positional = append(positional, arg)
			continue
		}
		if arg == "--" {
			terminator = true
			continue
		}
		if !looksLikeOption(arg) {
			positional = append(positional, arg)
			continue
		}

		if arg[1] == '-' {
			body := arg[2:]
			name := body
			var value string
			hasValue := false
			if k := strings.IndexByte(body, '='); k >= 0 {
				name, value, hasValue = body[:k], body[k+1:], true
			}
			opt := lookupLong(name)
			if opt == nil {
				return nil, nil, fmt.Errorf("unknown flag `%s'", name)
			}
			if opt.short == 'h' {
				if hasValue {
					return nil, nil, boolArgError(opt)
				}
				return nil, nil, errHelp
			}
			if !opt.arg {
				if hasValue {
					return nil, nil, boolArgError(opt)
				}
				st.setBool(opt)
				continue
			}
			if hasValue {
				if err := st.setCount(value, opt); err != nil {
					return nil, nil, err
				}
				continue
			}
			v, err, consumed := takeValue(argv, i, opt)
			if err != nil {
				return nil, nil, err
			}
			if err := st.setCount(v, opt); err != nil {
				return nil, nil, err
			}
			i += consumed
			continue
		}

		// short option cluster
		body := arg[1:]
		for j := 0; j < len(body); j++ {
			opt := lookupShort(body[j])
			if opt == nil {
				return nil, nil, fmt.Errorf("unknown flag `%c'", body[j])
			}
			if opt.short == 'h' {
				return nil, nil, errHelp
			}
			if !opt.arg {
				st.setBool(opt)
				continue
			}
			rest := body[j+1:]
			if rest == "" {
				v, err, consumed := takeValue(argv, i, opt)
				if err != nil {
					return nil, nil, err
				}
				if err := st.setCount(v, opt); err != nil {
					return nil, nil, err
				}
				i += consumed
				break
			}
			if j > 0 {
				// Only the first flag of a cluster may carry an inline
				// value.
				return nil, nil, expectedArgument(opt)
			}
			if rest[0] == '=' {
				rest = rest[1:]
			}
			if err := st.setCount(rest, opt); err != nil {
				return nil, nil, err
			}
			break
		}
	}

	return st, positional, nil
}

// takeValue consumes the next argument as the value for opt.
func takeValue(argv []string, i int, opt *option) (string, error, int) {
	if i+1 >= len(argv) {
		return "", expectedArgument(opt), 0
	}
	next := argv[i+1]
	if next == "--" {
		return "", fmt.Errorf("expected argument for flag `%s', but got double dash `--'", opt.plainName()), 0
	}
	if looksLikeOption(next) {
		return "", fmt.Errorf("expected argument for flag `%s', but got option `%s'", opt.plainName(), next), 0
	}
	return next, nil, 1
}

func (s *settings) setBool(opt *option) {
	switch opt.short {
	case 'P':
		s.privilege = true
	case 'V':
		s.version = true
	}
}

func (s *settings) setCount(v string, opt *option) error {
	n, err := strconv.ParseInt(v, 10, 64)
	if err != nil {
		return fmt.Errorf("invalid argument for flag `%s' (expected int): %s", opt.plainName(), err.Error())
	}
	s.count = n
	return nil
}

func boolArgError(opt *option) error {
	return fmt.Errorf("bool flag `%s' cannot have an argument", opt.plainName())
}

func expectedArgument(opt *option) error {
	return fmt.Errorf("expected argument for flag `%s'", opt.plainName())
}
GOEOF
echo written; gofmt -l args.go"}

