package main

import (
	"encoding/binary"
	"errors"
	"fmt"
	"net"
	"os"
	"syscall"
	"time"
	"unsafe"
)

// ICMP constants used by the ping implementation.
const (
	icmp4EchoRequest  = 8
	icmp4EchoReply    = 0
	icmp6EchoRequest  = 128
	icmp6EchoReply    = 129
	icmpHeaderLen     = 8
	icmpDataLen       = 24
	recvBufferSize    = 1500
	controlBufferSize = 256

	ipOptionRecvTTL    = 12
	ipAncillaryTTL     = 2
	ipv6OptionHopLimit = 41
)

var (
	errAddrEmpty = errors.New("addr cannot be empty")
)

// packet is a single received ICMP echo reply.
type packet struct {
	nbytes int
	ttl    int
	rtt    time.Duration
}

// conn wraps the socket used to exchange ICMP messages.
type conn struct {
	fd         int
	ipv4       bool
	privileged bool
	local      string // rendered local address, e.g. "0.0.0.0:1234"
	remote     string // rendered peer address,   e.g. "1.1.1.1:0"
	id         uint16
}

// resolve maps a host name or literal address to its IP address.
func resolve(host string) (net.IP, bool, error) {
	if host == "" {
		return nil, false, errAddrEmpty
	}
	addr, err := net.ResolveIPAddr("ip", host)
	if err != nil {
		return nil, false, err
	}
	ip := addr.IP
	if ip4 := ip.To4(); ip4 != nil {
		return ip4, true, nil
	}
	return ip, false, nil
}

// dial prepares the socket for the given address.  Unprivileged pings are
// carried by a datagram ICMP socket; privileged pings use a raw IP socket.
func dial(ip net.IP, ipv4, privileged bool) (*conn, error) {
	c := &conn{ipv4: ipv4, privileged: privileged}
	if ipv4 {
		c.remote = ip.String() + ":0"
		c.id = uint16(os.Getpid() & 0xffff)
	} else {
		c.remote = "[" + ip.String() + "]:0"
		c.id = uint16(os.Getpid() & 0xffff)
	}

	if !privileged {
		family, proto := syscall.AF_INET, syscall.IPPROTO_ICMP
		if !ipv4 {
			family, proto = syscall.AF_INET6, syscall.IPPROTO_ICMPV6
		}
		fd, err := syscall.Socket(family, syscall.SOCK_DGRAM, proto)
		if err != nil {
			return nil, fmt.Errorf("socket: %s", err)
		}
		var sa syscall.Sockaddr
		if ipv4 {
			sa = &syscall.SockaddrInet4{}
		} else {
			sa = &syscall.SockaddrInet6{}
		}
		if err := syscall.Bind(fd, sa); err != nil {
			syscall.Close(fd)
			return nil, fmt.Errorf("bind: %s", err)
		}
		c.fd = fd
		c.local = localName(fd, ipv4)
		return c, nil
	}

	network := "ip4:icmp"
	if !ipv4 {
		network = "ip6:ipv6-icmp"
	}
	pc, err := net.ListenPacket(network, "")
	if err != nil {
		return nil, err
	}
	file, err := pc.(*net.IPConn).(interface{ File() (*os.File, error) }).File()
	if err != nil {
		return nil, err
	}
	c.fd = int(file.Fd())
	c.local = localName(c.fd, ipv4)
	return c, nil
}

func localName(fd int, ipv4 bool) string {
	sa, err := syscall.Getsockname(fd)
	if err != nil {
		if ipv4 {
			return "0.0.0.0:0"
		}
		return "[::]:0"
	}
	switch a := sa.(type) {
	case *syscall.SockaddrInet4:
		ip := net.IP(a.Addr[:]).String()
		if ipv4 {
			return ip + ":" + itoa(a.Port)
		}
		return "[" + ip + "]:" + itoa(a.Port)
	case *syscall.SockaddrInet6:
		ip := net.IP(a.Addr[:]).String()
		return "[" + ip + "]:" + itoa(a.Port)
	}
	return ""
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [24]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

// close releases the socket.
func (c *conn) close() {
	if c.fd > 0 {
		syscall.Close(c.fd)
		c.fd = 0
	}
}

// enableTTLFeedback asks the kernel to report the TTL of every datagram.
func (c *conn) enableTTLFeedback() {
	if c.privileged {
		return
	}
	if c.ipv4 {
		syscall.SetsockoptInt(c.fd, syscall.IPPROTO_IP, ipOptionRecvTTL, 1)
		return
	}
	syscall.SetsockoptInt(c.fd, syscall.IPPROTO_IPV6, ipv6OptionHopLimit, 1)
}

func checksum(b []byte) uint16 {
	var sum uint32
	for i := 0; i+1 < len(b); i += 2 {
		sum += uint32(b[i])<<8 | uint32(b[i+1])
	}
	if len(b)%2 == 1 {
		sum += uint32(b[len(b)-1]) << 8
	}
	for sum>>16 != 0 {
		sum = (sum & 0xffff) + (sum >> 16)
	}
	return ^uint16(sum)
}

// buildEcho assembles an ICMP echo request.
func (c *conn) buildEcho(seq uint16, data []byte) []byte {
	msgType := byte(icmp4EchoRequest)
	if !c.ipv4 {
		msgType = icmp6EchoRequest
	}
	pkt := make([]byte, icmpHeaderLen+len(data))
	pkt[0] = msgType
	binary.BigEndian.PutUint16(pkt[4:6], c.id)
	binary.BigEndian.PutUint16(pkt[6:8], seq)
	copy(pkt[8:], data)
	if c.ipv4 {
		binary.BigEndian.PutUint16(pkt[2:4], checksum(pkt))
	}
	return pkt
}

// send transmits one echo request and returns the moment it left.
func (c *conn) send(seq uint16, data []byte) error {
	pkt := c.buildEcho(seq, data)
	sa := c.peerSockaddr()
	for {
		err := syscall.Sendto(c.fd, pkt, 0, sa)
		if err == syscall.EINTR {
			continue
		}
		if err != nil {
			return &net.OpError{
				Op: "write", Net: "udp", Source: addrString(c.local),
				Addr: addrString(c.remote), Err: err,
			}
		}
		return nil
	}
}

func addrString(s string) net.Addr {
	host, port, _ := net.SplitHostPort(s)
	ip := net.ParseIP(host)
	if ip == nil {
		return &net.IPAddr{}
	}
	p := 0
	for _, ch := range port {
		if ch < '0' || ch > '9' {
			p = 0
			break
		}
		p = p*10 + int(ch-'0')
	}
	return &net.UDPAddr{IP: ip, Port: p}
}

func (c *conn) peerSockaddr() syscall.Sockaddr {
	ip := net.ParseIP(strings.Trim(c.remote, "[]:0123456789"))
	if c.ipv4 {
		var sa syscall.SockaddrInet4
		copy(sa.Addr[:], ip.To4())
		return &sa
	}
	var sa syscall.SockaddrInet6
	copy(sa.Addr[:], ip.To16())
	return &sa
}

// receive waits for the next datagram and turns it into a packet.
func (c *conn) receive(sentAt time.Time, data []byte) (packet, error) {
	buf := make([]byte, recvBufferSize)
	ctl := make([]byte, controlBufferSize)
	n, oobn, _, _, err := syscall.Recvmsg(c.fd, buf, ctl, 0)
	if err != nil {
		return packet{}, err
	}
	msg := buf[:n]
	if c.privileged {
		msg = stripIPHeader(msg, c.ipv4)
	}
	ttl := parseTTL(c.ipv4, ctl[:oobn])
	if c.privileged {
		if t := headerTTL(msg, c.ipv4); t >= 0 {
			ttl = t
		}
	}
	rtt := time.Since(sentAt)
	return packet{nbytes: len(msg), ttl: ttl, rtt: rtt}, nil
}

// stripIPHeader removes the IP header from a datagram received on a raw
// socket, when there is one.
func stripIPHeader(b []byte, ipv4 bool) []byte {
	if len(b) < 1 {
		return b
	}
	if ipv4 {
		if b[0]>>4 != 4 || len(b) < 20 {
			return b
		}
		ihl := int(b[0]&0x0f) << 2
		if ihl < 20 || ihl > len(b) {
			return b
		}
		return b[ihl:]
	}
	if b[0]>>4 != 6 || len(b) < 40 {
		return b
	}
	return b[40:]
}

func headerTTL(b []byte, ipv4 bool) int {
	if ipv4 {
		if len(b) < 9 {
			return -1
		}
		return int(b[8])
	}
	return -1
}

// parseTTL extracts the TTL (or hop limit) from the ancillary data.
func parseTTL(ipv4 bool, ctl []byte) int {
	level, ctype := uint32(0), uint32(ipAncillaryTTL)
	if !ipv4 {
		level, ctype = uint32(syscall.IPPROTO_IPV6), uint32(ipv6OptionHopLimit)
	}
	for len(ctl) >= 16 {
		length := int(binary.LittleEndian.Uint32(ctl[0:4]))
		if length < 16 || length > len(ctl) {
			break
		}
		lv := binary.LittleEndian.Uint32(ctl[4:8])
		ty := binary.LittleEndian.Uint32(ctl[8:12])
		if lv == level && ty == ctype && length >= 20 {
			return int(int32(binary.LittleEndian.Uint32(ctl[16:20])))
		}
		ctl = ctl[aligned(length):]
	}
	return 0
}

func aligned(n int) int {
	if n%8 != 0 {
		n += 8 - n%8
	}
	return n
}

// pinger drives the exchange of echo messages.
type pinger struct {
	c         *conn
	count     int64
	interval  time.Duration
	privileged bool
	stats     statistics
}

// statistics collects the round trip measurements.
type statistics struct {
	sent int
	recv int
	rtts []time.Duration
}

func (s *statistics) add(d time.Duration) {
	s.recv++
	s.rtts = append(s.rtts, d)
}

func (s statistics) loss() float64 {
	if s.sent == 0 {
		return float64('n') / float64('n') // NaN
	}
	lost := s.sent - s.recv
	return float64(lost) / float64(s.sent) * 100
}

func (s statistics) min() time.Duration {
	if len(s.rtts) == 0 {
		return 0
	}
	m := s.rtts[0]
	for _, d := range s.rtts[1:] {
		if d < m {
			m = d
		}
	}
	return m
}

func (s statistics) max() time.Duration {
	if len(s.rtts) == 0 {
		return 0
	}
	m := s.rtts[0]
	for _, d := range s.rtts[1:] {
		if d > m {
			m = d
		}
	}
	return m
}

func (s statistics) avg() time.Duration {
	if len(s.rtts) == 0 {
		return 0
	}
	var sum time.Duration
	for _, d := range s.rtts {
		sum += d
	}
	return sum / time.Duration(len(s.rtts))
}

func (s statistics) stddev() time.Duration {
	if len(s.rtts) == 0 {
		return 0
	}
	avg := s.avg()
	var sum int64
	for _, d := range s.rtts {
		diff := int64(d - avg)
		sum += diff * diff
	}
	variance := sum / int64(len(s.rtts))
	return time.Duration(isqrt(uint64(variance)))
}

func isqrt(v uint64) uint64 {
	if v == 0 {
		return 0
	}
	x := v
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + v/x) / 2
	}
