// resolve maps a host name or literal address to its IP address.
func resolve(host string) (net.IP, bool, error) {
	if host == "" {
		return nil, false, errAddrEmpty
	}
	addr, err := net.ResolveIPAddr("ip", host)
	if err != nil {
		return nil, false, err
	}
	ip := addr.IP
	if ip4 := ip.To4(); ip4 != nil {
		return ip4, true, nil
	}
	return ip, false, nil
}

// dial prepares the socket for the given address.  Unprivileged pings are
// carried by a datagram ICMP socket; privileged pings use a raw IP socket.
func dial(ip net.IP, ipv4, privileged bool) (*conn, error) {
	c := &conn{ipv4: ipv4, privileged: privileged}
	if ipv4 {
		c.remote = ip.String() + ":0"
		c.id = uint16(os.Getpid() & 0xffff)
	} else {
		c.remote = "[" + ip.String() + "]:0"
		c.id = uint16(os.Getpid() & 0xffff)
	}

