// buildEcho assembles an ICMP echo request.
func (c *conn) buildEcho(seq uint16, data []byte) []byte {
	msgType := byte(icmp4EchoRequest)
	if !c.ipv4 {
		msgType = icmp6EchoRequest
	}
	pkt := make([]byte, icmpHeaderLen+len(data))
	pkt[0] = msgType
	binary.BigEndian.PutUint16(pkt[4:6], c.id)
	binary.BigEndian.PutUint16(pkt[6:8], seq)
	copy(pkt[8:], data)
	if c.ipv4 {
		binary.BigEndian.PutUint16(pkt[2:4], checksum(pkt))
	}
	return pkt
}

// send transmits one echo request and returns the moment it left.
func (c *conn) send(seq uint16, data []byte) error {
	pkt := c.buildEcho(seq, data)
	sa := c.peerSockaddr()
	for {
		err := syscall.Sendto(c.fd, pkt, 0, sa)
		if err == syscall.EINTR {
			continue
