	ipOptionRecvTTL    = 12 // IP_RECVTTL
	ipv6OptionHopLimit = 41 // IPV6_HOPLIMIT
)

var errAddrEmpty = errors.New("addr cannot be empty")

// resolve turns a host name or literal address into an IP address and
// reports whether it is an IPv4 address.
func resolve(host string) (net.IP, bool, error) {
	if host == "" {
		return nil, false, errAddrEmpty
	}
	addr, err := net.ResolveIPAddr("ip", host)
	if err != nil {
		return nil, false, err
	}
	if ip4 := addr.IP.To4(); ip4 != nil {
		return ip4, true, nil
	}
	return addr.IP, false, nil
}

// packet describes one received echo reply.
type packet struct {
	nbytes int
	ttl    int
	rtt    time.Duration
}

// socket holds the file descriptor used to exchange ICMP messages together
// with the strings needed to reproduce the error messages of the net
// package.
type socket struct {
	fd         int
	ipv4       bool
	privileged bool
	local      string
	remote     string
	ident      uint16
	peer       syscall.Sockaddr
}

// newSocket prepares the socket for the resolved address.  Privileged mode
// uses a raw IP socket, otherwise a datagram ICMP socket is used, which is
// what the kernel hands out to unprivileged processes.
func newSocket(ip net.IP, ipv4, privileged bool) (*socket, error) {
	s := &socket{ipv4: ipv4, privileged: privileged}
	if ipv4 {
		s.remote = ip.String() + ":0"
	} else {
		s.remote = "[" + ip.String() + "]:0"
	}

	if !privileged {
		family, proto := syscall.AF_INET, syscall.IPPROTO_ICMP
		if !ipv4 {
			family, proto = syscall.AF_INET6, syscall.IPPROTO_ICMPV6
		}
		fd, err := syscall.Socket(family, syscall.SOCK_DGRAM, proto)
		if err != nil {
			return nil, fmt.Errorf("socket: %s", err)
		}
		var sa syscall.Sockaddr
		if ipv4 {
			sa = &syscall.SockaddrInet4{}
		} else {
			sa = &syscall.SockaddrInet6{}
		}
		if err := syscall.Bind(fd, sa); err != nil {
			syscall.Close(fd)
			return nil, fmt.Errorf("bind: %s", err)
		}
		s.fd = fd
		s.local = localName(fd, ipv4)
		s.peer = peerAddr(ip, ipv4)
		s.ident = uint16(os.Getpid() & 0xffff)
		if ipv4 {
			if p, _, err := syscall.Getsockname(fd); err == nil {
				if a, ok := p.(*syscall.SockaddrInet4); ok {
					s.ident = uint16(a.Port)
				}
			}
		} else {
			if p, _, err := syscall.Getsockname(fd); err == nil {
				if a, ok := p.(*syscall.SockaddrInet6); ok {
					s.ident = uint16(a.Port)
				}
			}
		}
		return s, nil
	}

	network := "ip4:icmp"
	if !ipv4 {
		network = "ip6:ipv6-icmp"
	}
	pc, err := net.ListenPacket(network, "")
	if err != nil {
		return nil, err
	}
	ipc := pc.(*net.IPConn)
	file, err := ipc.File()
	if err != nil {
		return nil, err
	}
	s.fd = int(file.Fd())
	s.local = localName(s.fd, ipv4)
	s.peer = peerAddr(ip, ipv4)
	s.ident = uint16(os.Getpid() & 0xffff)
	return s, nil
}

func peerAddr(ip net.IP, ipv4 bool) syscall.Sockaddr {
	if ipv4 {
		var sa syscall.SockaddrInet4
		copy(sa.Addr[:], ip.To4())
		return &sa
	}
	var sa syscall.SockaddrInet6
	copy(sa.Addr[:], ip.To16())
	return &sa
}

func localName(fd int, ipv4 bool) string {
	sa, err := syscall.Getsockname(fd)
	if err != nil {
		if ipv4 {
			return "0.0.0.0:0"
		}
		return "[::]:0"
	}
	switch a := sa.(type) {
	case *syscall.SockaddrInet4:
		return net.IP(a.Addr[:]).String() + ":" + itoa(a.Port)
	case *syscall.SockaddrInet6:
		return "[" + net.IP(a.Addr[:]).String() + "]:" + itoa(a.Port)
	}
	return ""
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [24]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

func (s *socket) close() {
	if s.fd > 0 {
		syscall.Close(s.fd)
		s.fd = 0
	}
}

// watchTTL asks the kernel to hand the TTL of every datagram over as
// ancillary data.
func (s *socket) watchTTL() {
	if s.privileged {
		return
	}
	if s.ipv4 {
		syscall.SetsockoptInt(s.fd, syscall.IPPROTO_IP, ipOptionRecvTTL, 1)
		return
	}
	syscall.SetsockoptInt(s.fd, syscall.IPPROTO_IPV6, ipv6OptionHopLimit, 1)
}

func checksum(b []byte) uint16 {
	var sum uint32
	for i := 0; i+1 < len(b); i += 2 {
		sum += uint32(b[i])<<8 | uint32(b[i+1])
	}
	if len(b)%2 == 1 {
		sum += uint32(b[len(b)-1]) << 8
	}
	for sum>>16 != 0 {
		sum = (sum & 0xffff) + (sum >> 16)
	}
	return ^uint16(sum)
}

// buildEchoRequest assembles an ICMP echo request message.
func (s *socket) buildEchoRequest(seq uint16, data []byte) []byte {
	msgType := byte(icmp4EchoRequest)
	if !s.ipv4 {
		msgType = icmp6EchoRequest
	}
	pkt := make([]byte, icmpHeaderLen+len(data))
	pkt[0] = msgType
	binary.BigEndian.PutUint16(pkt[4:6], s.ident)
	binary.BigEndian.PutUint16(pkt[6:8], seq)
	copy(pkt[8:], data)
	if s.ipv4 {
		binary.BigEndian.PutUint16(pkt[2:4], checksum(pkt))
	}
	return pkt
}

// send writes one echo request to the peer.
func (s *socket) send(seq uint16, data []byte) error {
	pkt := s.buildEchoRequest(seq, data)
	for {
		err := syscall.Sendto(s.fd, pkt, 0, s.peer)
		if err == syscall.EINTR {
			continue
		}
		if err != nil {
			return &net.OpError{Op: "write", Net: "udp",
				Source: udpAddr(s.local), Addr: udpAddr(s.remote), Err: err}
		}
		return nil
	}
}

// udpAddr renders an "ip:port" pair the way the net package does so that
// error messages match.
func udpAddr(s string) net.Addr {
	host, port, err := net.SplitHostPort(s)
	if err != nil {
		return &net.IPAddr{}
	}
	p := 0
	for i := 0; i < len(port); i++ {
		if port[i] < '0' || port[i] > '9' {
			p = 0
			break
		}
		p = p*10 + int(port[i]-'0')
	}
	ip := net.ParseIP(host)
	if ip == nil {
		return &net.UDPAddr{Port: p}
	}
	return &net.UDPAddr{IP: ip, Port: p}
}

// receive reads one datagram and turns it into a packet.
func (s *socket) receive() (packet, uint16, error) {
	buf := make([]byte, recvBufferSize)
	ctl := make([]byte, controlSize)
	n, oobn, _, _, err := syscall.Recvmsg(s.fd, buf, ctl, 0)
	if err != nil {
		return packet{}, 0, err
	}
	msg := buf[:n]
	if s.privileged {
		msg = stripIPHeader(msg, s.ipv4)
	}
	if len(msg) < icmpHeaderLen {
		return packet{}, 0, errors.New("short packet")
	}
	seq := binary.BigEndian.Uint16(msg[6:8])
	return packet{nbytes: len(msg), ttl: extractTTL(s, msg, ctl[:oobn])}, seq, nil
}

// stripIPHeader removes the IP header of a datagram handed over by a raw
// socket.
func stripIPHeader(b []byte, ipv4 bool) []byte {
	if ipv4 {
		if len(b) < 20 || b[0]>>4 != 4 {
			return b
		}
		ihl := int(b[0]&0x0f) << 2
		if ihl < 20 || ihl > len(b) {
			return b
		}
		return b[ihl:]
	}
	if len(b) < 40 || b[0]>>4 != 6 {
		return b
	}
	return b[40:]
}

func extractTTL(s *socket, msg, ctl []byte) int {
	if s.privileged && s.ipv4 && len(msg) > 8 {
		return int(msg[8])
	}
	level, ctype := uint32(0), uint32(2)
	if !s.ipv4 {
		level, ctype = uint32(syscall.IPPROTO_IPV6), uint32(ipv6OptionHopLimit)
	}
	for len(ctl) >= 16 {
		length := int(binary.LittleEndian.Uint32(ctl[0:4]))
		if length < 16 || length > len(ctl) {
			break
		}
		lv := binary.LittleEndian.Uint32(ctl[4:8])
		ty := binary.LittleEndian.Uint32(ctl[8:12])
		if lv == level && ty == ctype && length >= 20 {
			return int(int32(binary.LittleEndian.Uint32(ctl[16:20])))
		}
		step := length
		if step%8 != 0 {
			step += 8 - step%8
		}
		ctl = ctl[step:]
	}
	return 0
}

// statistics accumulates the measurements of a run.
type statistics struct {
	sent int
	recv int
	rtts []time.Duration
}

func (st *statistics) loss() float64 {
	return float64(st.sent-st.recv) / float64(st.sent) * 100
}

func (st *statistics) min() time.Duration {
	if len(st.rtts) == 0 {
		return 0
	}
	m := st.rtts[0]
	for _, d := range st.rtts[1:] {
		if d < m {
			m = d
		}
	}
	return m
}

func (st *statistics) max() time.Duration {
	if len(st.rtts) == 0 {
		return 0
	}
	m := st.rtts[0]
	for _, d := range st.rtts[1:] {
		if d > m {
			m = d
		}
	}
	return m
}

func (st *statistics) avg() time.Duration {
	if len(st.rtts) == 0 {
		return 0
	}
	var sum time.Duration
	for _, d := range st.rtts {
		sum += d
	}
	return sum / time.Duration(len(st.rtts))
}

func (st *statistics) stddev() time.Duration {
	if len(st.rtts) == 0 {
		return 0
	}
	avg := st.avg()
	var sum int64
	for _, d := range st.rtts {
		diff := int64(d - avg)
		sum += diff * diff
	}
	return time.Duration(isqrt(uint64(sum / int64(len(st.rtts)))))
}

func isqrt(v uint64) uint64 {
	if v == 0 {
		return 0
	}
	x, y := v, (v+1)/2
	for y < x {
		x, y = y, (y+v/y)/2
	}
	return x
}

// pinger drives one ping run.
type pinger struct {
	sock      *socket
	count     int64
	interval  time.Duration
	privileged bool
	stats     statistics

	sentAt   map[uint16]time.Time
	received map[uint16]bool
}

func newPinger(sock *socket, count int64, interval time.Duration) *pinger {
	return &pinger{
		sock:      sock,
		count:     count,
		interval:  interval,
		privileged: sock.privileged,
		sentAt:    make(map[uint16]time.Time),
		received:  make(map[uint16]bool),
	}
}

// run exchanges echo messages until enough replies arrived, the peer is no
// longer reachable or the user interrupts the run.
func (p *pinger) run(handle func(packet)) error {
	p.sock.watchTTL()

	pending := make(chan packet, 64)
	failure := make(chan error, 1)
	stopped := make(chan struct{})
	defer close(stopped)

	go func() {
		defer close(pending)
		for {
			pkt, seq, err := p.sock.receive()
			if err != nil {
				select {
				case failure <- err:
				default:
				}
				return
			}
			select {
			case pending <- packet{nbytes: pkt.nbytes, ttl: pkt.ttl,
				rtt: elapsed(p.sentAt[seq]), seq: seq}:
			case <-stopped:
				return
			}
		}
	}()

	if err := p.sendOne(0); err != nil {
		return err
	}
	ticker := time.NewTicker(p.interval)
	defer ticker.Stop()

	interrupt := make(chan os.Signal, 1)
	signal.Notify(interrupt, os.Interrupt)
	defer signal.Stop(interrupt)

	for {
		if p.count > 0 && p.stats.recv >= p.count {
			return nil
		}
		select {
		case <-interrupt:
			return nil
		case err := <-failure:
			return err
		case pkt := <-pending:
			p.record(pkt, handle)
		case <-ticker.C:
			if p.count > 0 && p.stats.sent >= p.count {
				continue
			}
			if err := p.sendOne(nextSeq(p)); err != nil {
				return err
			}
		}
	}
}

func elapsed(t time.Time) time.Duration {
	if t.IsZero() {
		return 0
	}
	return time.Since(t)
}

func (p *pinger) record(pkt packet, handle func(packet)) {
	if pkt.seq == 0 || p.received[pkt.seq] {
		return
	}
	if _, ok := p.sentAt[pkt.seq]; !ok {
		return
	}
	p.received[pkt.seq] = true
	p.stats.recv++
	p.stats.rtts = append(p.stats.rtts, pkt.rtt)
	handle(pkt)
}

func nextSeq(p *pinger) uint16 {
	var seq uint16
	for {
		if _, ok := p.sentAt[seq]; !ok {
			return seq
		}
		seq++
	}
}

func (p *pinger) sendOne(seq uint16) error {
	data := make([]byte, icmpDataLen)
	binary.BigEndian.PutUint64(data, uint64(time.Now().UnixNano()))
	if err := p.sock.send(seq, data); err != nil {
		return err
	}
	p.sentAt[seq] = time.Now()
	p.stats.sent++
	return nil
}

