package main

import (
	"encoding/binary"
	"fmt"
	"net"
	"os"
	"syscall"
	"time"
)

func csum(b []byte) uint16 {
	var s uint32
	for i := 0; i+1 < len(b); i += 2 { s += uint32(b[i])<<8 | uint32(b[i+1]) }
	if len(b)%2 == 1 { s += uint32(b[len(b)-1]) << 8 }
	for s>>16 != 0 { s = (s & 0xffff) + (s >> 16) }
	return ^uint16(s)
}

func main() {
	fd, err := syscall.Socket(syscall.AF_INET6, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMPV6)
	if err != nil { fmt.Println("socket:", err); return }
	defer syscall.Close(fd)
	if err := syscall.Bind(fd, &syscall.SockaddrInet6{}); err != nil { fmt.Println("bind:", err); return }
	for _, opt := range []int{41 /*HOPLIMIT*/, 49 /*RECVPKTINFO*/, 50, 8} {
		err := syscall.SetsockoptInt(fd, syscall.IPPROTO_IPV6, opt, 1)
		fmt.Printf("setsockopt(IPPROTO_IPV6, %d) err=%v\n", opt, err)
	}
	sa, err := syscall.Getsockname(fd)
	port := 0
	if a, ok := sa.(*syscall.SockaddrInet6); ok { port = a.Port }
	fmt.Println("port:", port)
	// send echo request
	data := make([]byte, 24)
	for i := range data { data[i] = byte(i) }
	pkt := make([]byte, 32)
	pkt[0] = 128
	binary.BigEndian.PutUint16(pkt[4:6], uint16(port))
	binary.BigEndian.PutUint16(pkt[6:8], 1)
	copy(pkt[8:], data)
	dst := &syscall.SockaddrInet6{}
	copy(dst.Addr[:], net.ParseIP("::1").To16())
	if err := syscall.Sendto(fd, pkt, 0, dst); err != nil { fmt.Println("sendto:", err); return }
	buf := make([]byte, 2000)
	ctl := make([]byte, 512)
	deadline := time.Now().Add(300 * time.Millisecond)
	for time.Now().Before(deadline) {
		n, oobn, _, _, err := syscall.Recvmsg(fd, buf, ctl, 0)
		fmt.Printf("recvmsg n=%d oobn=%d err=%v ctl=%x\n", n, oobn, err, ctl[:oobn])
		if err == nil && n > 0 { break }
	}
	_ = os.Stdout
}
