import re, subprocess, sys, os
def norm(s):
    s = re.sub(r'\x1b\[[0-9;]*m', '', s)          # strip colours
    s = re.sub(r'time=[0-9.]+Â?s', 'time=X', s)   # mask round trip times
    s = re.sub(r'(min|avg|max|stddev)=[0-9.]+Â?s', r'\1=X', s)
    s = re.sub(r'(?m)^Script (started|done).*\n?', '', s)
    return s
def run(cmd, env=None, timeout=60):
    e = dict(os.environ)
    if env: e.update(env)
    try:
        p = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=timeout, env=e, cwd='/workspace')
        return norm(p.stdout), norm(p.stderr), p.returncode
    except subprocess.TimeoutExpired as t:
        return norm(t.stdout or ''), norm(t.stderr or ''), 'TIMEOUT'
def cmp(args, timeout=60, label=None):
    a = run('./executable ' + args, timeout=timeout)
    b = run('./myexecutable ' + args, timeout=timeout)
    ok = (a == b)
    print(("OK  " if ok else "DIFF") + " [" + (label or args) + "] rc=%s/%s" % (a[2], b[2]))
    if not ok:
        for i in range(3):
            if a[i] != b[i]:
                print("   --- orig:", repr(a[i])[:400])
                print("   --- mine:", repr(b[i])[:400])
    return ok
